facts, list(.bag_read$record))   .bootstrap_lineage <- .bag_read$lineage } else {   stop("No bootstrap output found. This screen is a long job -- days, not ",        "minutes -- and is run from a companion script rather than inside this ",        "render, because the run writes nothing until its final replicate.
