bag", .bag_files[[.i]])) } # A callout, not a table cell. A provisional report that cannot say so is the # failure being prevented, and it must survive someone receiving the .html # without knowing when it was made -- which a number buried in a provenance # table does not. .shortfall <- boot_shortfall(bag, EXPECT_CHUNKS, EXPECT_BOOT) if (!is.null(.shortfall)) {   cat("
::: {.callout-warning title="Provisional -- this pool is incomplete"}
")   cat(.shortfall, "
", sep = "")   # The box under the title was printed before this was known; the end table says draft.   hvtiRtemplates:::.run_mark_draft("the bootstrap pool is incomplete")   cat(":::

