.unknown <- setdiff(names(OVERRIDES), paste0("pm", K_RANGE)) if (length(.unknown)) {   stop("OVERRIDES names solution(s) that are not in K_RANGE: ", toString(.unknown),        ". Name them pm<K>, such as pm4, for a K in ", toString(K_RANGE), ".", call. = FALSE) } .pm <- as.data.frame(lapply(sid_pam[paste0("pm", K_RANGE)], function(p) p$clustering)) .letters <- sid_align_labels(.pm, OVERRIDES) sid_letters <- data.frame(sid_ids, .letters, check.names = FALSE) names(sid_letters) <- c(.id, paste0("C", K_RANGE)) .sizes <- do.call(rbind, lapply(K_RANGE, function(k) {   tab <- table(.letters[, paste0("pm", k)], .pm[[paste0("pm", k)]])   data.frame(K = k, letter = rownames(tab), pam = colnames(tab)[apply(tab, 1, which.max)],              n = as.integer(rowSums(tab))) })) .shown <- .sizes .shown$smallest <- ifelse(.sizes$n == stats::ave(.sizes$n, .sizes$K, FUN = min), "smallest at this K", "") knitr::kable(.shown, row.names = FALSE) .small <- if (!is.null(K)) .sizes[.sizes$K == K & .sizes$n < MIN_SIZE, ] else .sizes[0, ] if (nrow(.small)) {   warning("At K = ", K, ", cluster(s) ", toString(.small$letter), " hold fewer than ", MIN_SIZE, " patients.",           call. = FALSE) } # In its own chunk because a callout is markdown, which only an asis chunk emits. if (nrow(.small)) {   cat("
::: {.callout-warning}
At K = ", K, ", cluster(s) ", toString(.small$letter), " hold fewer than ",       MIN_SIZE, " patients, too few for per-cluster tables or a vp-fit to say much.
:::
", sep = "") } # A Sankey needs two or more K to follow patients between. if (length(K_RANGE) > 1L) {   .sk <- hvtiPlotR::hv_sankey(sid_letters, cluster_cols = paste0("C", K_RANGE))   .plt_sankey <- plot(.sk) + hvtiPlotR::theme_hv_manuscript(base_size = 12)   # The page is 6.5 in wide; the Sankey's columns need its full width.   save_figure(.plt_sankey, "sid-clusters-sankey", width = 6.5, height = 6)   .plt_sankey } if (length(K_RANGE) < 2L) {   cat("
