.rules <- c(sub("^elig_", "", grep("^elig_", names(r), value = TRUE))) .sens <- do.call(base::rbind, lapply(c("combined", .rules), function(rule) {   keep <- if (rule == "combined") r$elig else r[[paste0("elig_", rule)]]   do.call(base::rbind, lapply(split(r[keep, ], r$received[keep]), function(x) {     q <- stats::quantile(x$diff, c(0.15, 0.5, 0.85), names = FALSE)     data.frame(rule = rule, arm = x$received[1L], kept = nrow(x), p15 = q[1], median = q[2], p85 = q[3],                favor_first = mean(x$diff > 0))   })) })) knitr::kable(.sens, digits = 2, row.names = FALSE) .dd <- merge(r[!r$no_arm, c("ID", "received", "diff")],              .vt$eligibility$rows[, c("ID", "method", "arm", "distance", "reference", "ratio", "in_distribution")],              by = "ID") .dd_none <- sum(!is.finite(.dd$distance)) .dd <- .dd[is.finite(.dd$distance), , drop = FALSE] if (.dd_none) cat(.dd_none, "patient-by-method distance(s) are unavailable (no predictor in common) and not drawn.

") if (!nrow(.dd)) {   cat("No treated patient has a distance to draw.
") } else {   # The median gap is not saved; ratio is distance over it, so any row with a positive ratio recovers it.   .lines <- do.call(base::rbind, lapply(split(.dd, list(.dd$method, .dd$arm), drop = TRUE), function(x) {     k <- which(is.finite(x$ratio) & x$ratio > 0)[1L]     data.frame(method = x$method[1L], arm = x$arm[1L], reference = x$reference[1L],                median = if (is.na(k)) NA_real_ else x$distance[k] / x$ratio[k])   }))   # Keys, not arm names: an arm may itself be called "neither". The scale below puts the names back.   .dd$favors <- factor(ifelse(.dd$diff > 0, "first", ifelse(.dd$diff < 0, "second", "tie")),                        levels = c("first", "second", "tie"))   .dd$panel <- paste("Received", .dd$received)   # A treated patient is judged against the other arm, so that arm's lines belong in the panel of the arm received.   .lines$panel <- paste("Received", ifelse(.lines$arm == ARMS[1], ARMS[2], ARMS[1]))   .fig <- ggplot(.dd, aes(x = distance, y = diff)) +     geom_hline(yintercept = 0, color = "gray40") +     geom_vline(data = .lines, aes(xintercept = reference), linetype = "dashed") +     geom_vline(data = .lines[!is.na(.lines$median), , drop = FALSE], aes(xintercept = median), linetype = "dotted") +     geom_point(aes(color = favors), alpha = 0.7, size = 1.4) +     geom_point(data = .dd[!.dd$in_distribution, , drop = FALSE], shape = 1, size = 3.4, stroke = 0.9,                color = "#B2182B") +     facet_grid(method ~ panel, scales = "free_x") +     labs(x = "Distance to the nearest patient of the other arm",          y = paste0("RMST difference (", ARMS[1], " minus ", ARMS[2], ")"), color = "Favors") +     scale_color_discrete(breaks = c("first", "second", "tie"), labels = c(ARMS, "neither")) +     theme(legend.position = "bottom")   save_figure(.fig, "vt-explain-distance")   .fig } if (nrow(.dd)) {   .dist_tab <- do.call(base::rbind, lapply(split(.dd, list(.dd$method, .dd$received), drop = TRUE), function(x) {     data.frame(method = x$method[1L], received = x$received[1L], patients = nrow(x),                out_of_distribution = sum(!x$in_distribution),                # A column that does not vary has no rank correlation; NA, not a warning.                spearman = if (nrow(x) > 2L && stats::sd(x$diff) > 0 && stats::sd(x$distance) > 0) {                  stats::cor(x$diff, x$distance, method = "spearman")                } else {                  NA_real_                })   }))   knitr::kable(.dist_tab, digits = 2, row.names = FALSE) }

